const input = $input.item.json;
const now = new Date();
const dateStr = now.toLocaleDateString('es-MX', { timeZone: 'America/Mexico_City' }) + ' ' + now.toLocaleTimeString('es-MX', { timeZone: 'America/Mexico_City', hour: '2-digit', minute: '2-digit' });

const delivType = input.delivery_type === 'domicilio' ? '🛵 A DOMICILIO' : '🥡 PARA LLEVAR (RECOGER)';

let message = `🍣 *NUEVO PEDIDO - RESTAURANTE RYU* 🍱\n`;
message += `━━━━━━━━━━━━━━━━━━━━━\n`;
message += `📅 *Fecha:* ${dateStr}\n`;
message += `👤 *Cliente:* ${input.customer_name || 'No especificado'}\n`;
message += `📱 *Teléfono:* ${input.customer_phone || 'No especificado'}\n`;
message += `📍 *Modalidad:* ${delivType}\n`;

if (input.delivery_type === 'domicilio') {
  message += `🏠 *Dirección:* ${input.address || 'Pendiente'}\n`;
  if (input.references) message += `📌 *Referencias:* ${input.references}\n`;
}

message += `━━━━━━━━━━━━━━━━━━━━━\n`;
message += `📝 *PLATILLOS PEDIDOS:*\n${input.items_summary}\n`;
message += `━━━━━━━━━━━━━━━━━━━━━\n`;
message += `💵 *TOTAL A COBRAR:* $${input.total_amount} MXN\n`;
message += `💳 *Método de Pago:* ${input.payment_method || 'Efectivo'}\n`;

if (input.payment_change_for) {
  const change = Number(input.payment_change_for) - Number(input.total_amount);
  message += `💰 *Paga con:* $${input.payment_change_for} (Cambio: $${change >= 0 ? change : 0})\n`;
}

message += `━━━━━━━━━━━━━━━━━━━━━\n`;
message += `⏳ *Estado:* 🟡 En Espera de Preparación`;

return {
  json: {
    formattedMessage: message
  }
};
